<script setup lang="ts">
import TenantPageSharing from '../../components/tenant/TenantPageSharing.vue'
import AdminConsole from '../../components/console/AdminConsole.vue'
import ConsolePageHeading from '@orangezh1/qisvc-console-ui/components/ConsolePageHeading'
import ConsoleInput from '@orangezh1/qisvc-console-ui/components/ConsoleInput'
import type {DecorationRoute} from '../../utils/decoration'
definePageMeta({layout:'tenant',key:route=>route.path})
type View={applicationKey:string|null;applications:{key:string;name:string}[];items:DecorationRoute[]}
const auth=useApi('tenant'),tenantId=useTenantContext().tenantId.value,endpoint='/admin/tenants/'+encodeURIComponent(tenantId)+'/page-routes',toast=useToast()
const initial=await useAsyncData('decoration-routes:'+auth.session.value?.id+':'+tenantId,(_,{signal})=>auth.api<View>(endpoint,'GET',undefined,{signal}))
const shareOpen=ref(false),sharePage=ref<'home'|'profile'>('home')
const data=ref(initial.data.value),error=ref(initial.error.value?.message||''),search=ref(''),group=ref('全部'),busy=ref(false),copying=ref('')
const groups=computed(()=>['全部',...new Set((data.value?.items||[]).map(i=>i.group))]),items=computed(()=>(data.value?.items||[]).filter(i=>(group.value==='全部'||i.group===group.value)&&(!search.value.trim()||(i.label+' '+i.path).toLowerCase().includes(search.value.trim().toLowerCase()))))
const life=new AbortController();let disposed=false
async function refresh(key=data.value?.applicationKey||''){if(busy.value)return;busy.value=true;error.value='';try{const result=await auth.api<View>(endpoint+(key?'?applicationKey='+encodeURIComponent(key):''),'GET',undefined,{signal:life.signal});if(!disposed)data.value=result}catch(e:any){if(!disposed)error.value=e.message}finally{if(!disposed)busy.value=false}}
async function copy(item:DecorationRoute){if(copying.value)return;copying.value=item.key;try{await navigator.clipboard.writeText(item.path);if(!disposed)toast.add({title:'页面路径已复制',color:'success'})}catch{if(!disposed)toast.add({title:'复制失败，请手动选择路径复制',color:'error'})}finally{if(!disposed)copying.value=''}}
onBeforeUnmount(()=>{disposed=true;life.abort()})
</script>
<template><AdminConsole :refreshing="busy" @refresh="refresh()"><div class="space-y-5"><ConsolePageHeading title="页面路径"/><UAlert v-if="error" color="error" :title="error"/><section class="surface-card overflow-hidden"><div class="flex flex-wrap items-center gap-3 p-5 border-b border-default"><div class="w-full sm:w-72"><ConsoleInput v-model="search" placeholder="搜索页面名称或路径" aria-label="搜索页面路径"/></div><select v-model="group" class="route-select" aria-label="页面分类"><option v-for="g in groups" :key="g">{{g}}</option></select><select v-if="data&&data.applications.length>1" class="route-select" :value="data.applicationKey||''" :disabled="busy" aria-label="选择应用" @change="refresh(($event.target as HTMLSelectElement).value)"><option value="" disabled>选择应用</option><option v-for="app in data.applications" :key="app.key" :value="app.key">{{app.name}}</option></select><span class="ml-auto text-xs text-muted">{{items.length}} 个可用页面</span></div><div class="overflow-x-auto"><table class="w-full text-sm text-left"><thead class="bg-elevated text-muted"><tr><th class="p-4 pl-5 font-medium">页面名称</th><th class="p-4 font-medium">分类</th><th class="p-4 font-medium">页面路径</th><th class="p-4 font-medium">操作</th><th class="p-4 font-medium">分享设置</th></tr></thead><tbody><tr v-for="item in items" :key="item.key" class="border-t border-default"><td class="p-4 pl-5 whitespace-nowrap">{{item.label}}</td><td class="p-4 whitespace-nowrap text-muted">{{item.group}}</td><td class="p-4"><code class="text-xs select-all">{{item.path}}</code></td><td class="p-4"><UButton size="xs" variant="ghost" icon="i-lucide-copy" :loading="copying===item.key" :disabled="!!copying" @click="copy(item)">复制</UButton></td><td class="p-4"><UButton v-if="['home','profile'].includes(item.key)" variant="ghost" size="xs" @click="sharePage=item.key as 'home'|'profile';shareOpen=true">分享设置</UButton><span v-else class="text-muted">—</span></td></tr></tbody></table></div><p v-if="!items.length" class="p-10 text-center text-muted text-sm">没有匹配的页面</p><p class="p-5 text-xs text-muted border-t border-default">页面由已开通的应用注册。装修组件和底部导航使用同一份页面目录，不接受手写任意跳转地址。</p><TenantPageSharing v-if="shareOpen&&data?.applicationKey" v-model:open="shareOpen" :tenant-id="tenantId" :application-key="data.applicationKey" :page="sharePage"/></section></div></AdminConsole></template>
<style scoped>.route-select{border:1px solid var(--ui-border);border-radius:6px;padding:7px 10px;background:var(--ui-bg);font-size:13px}</style>
